func describeLastInteraction(at *time.Time, now time.Time) string {
	days := DaysSince(at, now)
	switch {
	case days < 0:
		return "아직 기록 없음"
	case days == 0:
		return "오늘"
	case days < 30:
		return fmt.Sprintf("%d일 전", days)
	case days < 365:
		return fmt.Sprintf("약 %d개월 전", days/30)
	default:
		return fmt.Sprintf("약 %d년 전", days/365)
	}
}

